from datetime import datetime, timedelta, timezone

import pytest

from domain import BloodGroup, can_donate_red_cells, compatible_donor_groups, is_eligible

# Written by hand from the standard red-cell chart, NOT generated by the code under test.
EXPECTED = {
    "O-": {"O-"},
    "O+": {"O+", "O-"},
    "A-": {"A-", "O-"},
    "A+": {"A+", "A-", "O+", "O-"},
    "B-": {"B-", "O-"},
    "B+": {"B+", "B-", "O+", "O-"},
    "AB-": {"AB-", "A-", "B-", "O-"},
    "AB+": {"AB+", "AB-", "A+", "A-", "B+", "B-", "O+", "O-"},
}


@pytest.mark.parametrize("recipient", list(EXPECTED))
def test_compatible_donors_match_chart(recipient):
    got = {g.value for g in compatible_donor_groups(BloodGroup(recipient))}
    assert got == EXPECTED[recipient]


def test_total_compatible_pairs_is_27():
    pairs = [(d, r) for d in BloodGroup for r in BloodGroup if can_donate_red_cells(d, r)]
    assert len(pairs) == 27


def test_universal_donor_and_recipient():
    assert all(can_donate_red_cells(BloodGroup.O_NEG, r) for r in BloodGroup)
    assert all(can_donate_red_cells(d, BloodGroup.AB_POS) for d in BloodGroup)


NOW = datetime(2026, 10, 7, 12, 0, tzinfo=timezone.utc)


def test_never_donated_is_eligible():
    assert is_eligible(None, NOW) is True


def test_eligibility_boundary_is_inclusive_at_90_days():
    assert is_eligible(NOW - timedelta(days=90), NOW) is True
    assert is_eligible(NOW - timedelta(days=89, hours=23), NOW) is False


def test_interval_is_configurable():
    last = NOW - timedelta(days=100)
    assert is_eligible(last, NOW, min_interval_days=120) is False